.ds-button{display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 26px;
  min-height: 54px;
  padding: 15px 23px;
  border: 1px solid transparent;
  border-radius: 7px;
  background: var(--brand,#14b8a6);
  color: #12332c;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 650;
  transition:
    background-color 0.2s,
    transform 0.2s;}
.ds-button:hover{background: #37c8b4;
  transform: translateY(-2px);}
.ds-button:active{transform: translateY(0);}
.ds-button-small{min-height: 43px;
  padding: 11px 17px;
  gap: 17px;
  font-size: 13px;}.ds-button{font-family:"Inter",ui-sans-serif,system-ui,sans-serif}.ds-button:focus-visible{outline:3px solid var(--brand-deep,#087f70);outline-offset:5px;border-radius:3px}.ds-button:disabled{opacity:.65;cursor:wait}
@media(prefers-reduced-motion:reduce){.ds-button,.ds-text-link svg,.ds-contact-form-wrap input,.ds-desktop-nav a,.ds-scenario-tabs button,.ds-faq-list summary svg{transition-duration:.01ms!important;animation-duration:.01ms!important;animation-iteration-count:1!important}}

