.ds-text-link{display: inline-flex;
  align-items: center;
  gap: 10px;
  width: fit-content;
  min-height: 44px;
  font-size: 14px;
  font-weight: 600;
  border: 0;
  background: transparent;
  padding: 0;}
.ds-text-link:hover{text-decoration: underline;}
.ds-text-link svg{transition: transform 0.2s;}
.ds-text-link:hover svg{transform: translate(2px, -2px);}.ds-text-link{font-family:"Inter",ui-sans-serif,system-ui,sans-serif;color:var(--ink,#16332f);color:var(--brand-deep,#087f70);text-decoration:none;text-underline-offset:5px}.ds-text-link:focus-visible{outline:3px solid var(--brand-deep,#087f70);outline-offset:5px;border-radius:3px}
