.ds-contact-form-wrap label{display: block;
  font-size: 12px;
  font-weight: 550;
  margin-bottom: 19px;}
.ds-contact-form-wrap input,
.ds-contact-form-wrap textarea,
.ds-contact-form-wrap select{display: block;
  width: 100%;
  background: #f8fcfa;
  border: 1px solid #b6d0c4;
  border-radius: 5px;
  min-height: 47px;
  padding: 12px 14px;
  margin-top: 8px;
  font-size: 13px;
  line-height: 1.5;
  caret-color: var(--brand-deep,#087f70);
  font-weight: 400;
  transition: border-color 0.2s;}
.ds-contact-form-wrap input:hover,
.ds-contact-form-wrap select:hover,
.ds-contact-form-wrap textarea:hover{border-color: #6d9e8d;}
.ds-contact-form-wrap input::placeholder,
.ds-contact-form-wrap textarea::placeholder{color: #5b736a;
  opacity: 1;}
.ds-contact-form-wrap textarea{resize: vertical;
  min-height: 104px;}
.ds-contact-form-wrap :is(input, textarea, select):focus-visible{outline-width: 2px;
  outline-offset: 2px;}.ds-contact-form-wrap{font-family:"Inter",ui-sans-serif,system-ui,sans-serif;color:var(--ink,#16332f);}.ds-contact-form-wrap input{box-sizing:border-box;color:inherit;font-family:inherit}.ds-contact-form-wrap input:focus-visible{outline:2px solid var(--brand-deep,#087f70);outline-offset:2px}@media(max-width:600px){.ds-contact-form-wrap label{font-size:13px}.ds-contact-form-wrap input{font-size:16px;padding-inline:12px}}
@media(prefers-reduced-motion:reduce){.ds-button,.ds-text-link svg,.ds-contact-form-wrap input,.ds-desktop-nav a,.ds-scenario-tabs button,.ds-faq-list summary svg{transition-duration:.01ms!important;animation-duration:.01ms!important;animation-iteration-count:1!important}}

.ds-desktop-nav{display: flex;
  align-items: center;
  gap: 31px;
  margin-left: auto;}
.ds-desktop-nav a{display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 13px;
  font-weight: 500;
  color: var(--muted,#536b66);
  transition: color 0.2s;}
.ds-desktop-nav a:hover{color: var(--brand-deep,#087f70);}.ds-desktop-nav{font-family:"Inter",ui-sans-serif,system-ui,sans-serif;color:var(--ink,#16332f);}.ds-desktop-nav a{text-decoration:none}.ds-desktop-nav a:focus-visible{outline:3px solid var(--brand-deep,#087f70);outline-offset:5px;border-radius:3px}
@media(prefers-reduced-motion:reduce){.ds-button,.ds-text-link svg,.ds-contact-form-wrap input,.ds-desktop-nav a,.ds-scenario-tabs button,.ds-faq-list summary svg{transition-duration:.01ms!important;animation-duration:.01ms!important;animation-iteration-count:1!important}}

.ds-scenario-tabs{display: flex;
  gap: 2px;
  padding: 4px;
  background: #d2eae1;
  border-radius: 7px;}
.ds-scenario-tabs button{border: 0;
  background: transparent;
  min-height: 36px;
  padding: 8px 15px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 550;
  transition: background-color 0.2s;}
.ds-scenario-tabs button[aria-selected="true"]{background: var(--white,#fff);}
.ds-scenario-tabs button:hover{background: #f7fcfa;}.ds-scenario-tabs{width:fit-content;font-family:"Inter",ui-sans-serif,system-ui,sans-serif;color:var(--ink,#16332f);}.ds-scenario-tabs button{font-family:inherit;color:inherit;cursor:pointer}.ds-scenario-tabs button:focus-visible{outline:3px solid var(--brand-deep,#087f70);outline-offset:5px;border-radius:3px}@media(max-width:600px){.ds-scenario-tabs button{min-height:37px;padding-inline:14px;font-size:11px}}
@media(prefers-reduced-motion:reduce){.ds-button,.ds-text-link svg,.ds-contact-form-wrap input,.ds-desktop-nav a,.ds-scenario-tabs button,.ds-faq-list summary svg{transition-duration:.01ms!important;animation-duration:.01ms!important;animation-iteration-count:1!important}}

.ds-flow-lab{border-radius: var(--radius,12px);
  padding: 27px 34px 18px;
  background: var(--mint,#e4f5f0);}
.ds-flow-topline{display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;}
.ds-flow-topline h2{font-size: 21px;
  font-weight: 550;
  letter-spacing: -0.025em;}
.ds-flow-nodes{display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  padding-block: 39px 33px;
  column-gap: 32px;}
.ds-flow-node{position: relative;
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 13px;}
.ds-node-symbol{position: relative;
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  background: #f8fcfa;
  border-radius: 10px;
  color: var(--brand-deep,#087f70);
  transition:
    background-color 0.3s,
    color 0.3s,
    box-shadow 0.3s;}
.ds-flow-node.ds-is-current .ds-node-symbol{background: var(--ink,#16332f);
  color: var(--white,#fff);
  box-shadow: 0 5px 12px -5px #16332f50;}
.ds-flow-node.ds-is-complete .ds-node-symbol{background: #b5e9d7;
  color: #155a43;}
.ds-node-copy h3{font-size: 13px;
  font-weight: 650;
  line-height: 1.4;
  margin-bottom: 4px;}
.ds-node-copy p{color: var(--muted,#536b66);
  font-size: 11px;
  line-height: 1.6;}
.ds-flow-disclaimer{font-size: 10px;
  color: var(--muted,#536b66);
  line-height: 1.6;
  margin-top: 10px;}.ds-flow-lab{font-family:"Inter",ui-sans-serif,system-ui,sans-serif;color:var(--ink,#16332f);}.ds-flow-lab h2,.ds-flow-lab h3,.ds-flow-lab p{margin:0}.ds-flow-lab h2{line-height:1.13}.ds-flow-lab .ds-flow-nodes{grid-template-columns:1fr}.ds-flow-lab .ds-flow-disclaimer{margin-top:10px}@media(max-width:600px){.ds-flow-lab{padding:22px 19px 16px}.ds-node-symbol{width:42px;height:42px;border-radius:9px}.ds-node-copy h3{font-size:14px}.ds-flow-disclaimer{font-size:11px;line-height:1.7}}
@media(prefers-reduced-motion:reduce){.ds-button,.ds-text-link svg,.ds-contact-form-wrap input,.ds-desktop-nav a,.ds-scenario-tabs button,.ds-faq-list summary svg{transition-duration:.01ms!important;animation-duration:.01ms!important;animation-iteration-count:1!important}}

.ds-faq-list details{border-top: 1px solid var(--line,#dbe7e2);}
.ds-faq-list details:last-child{border-bottom: 1px solid var(--line,#dbe7e2);}
.ds-faq-list summary{display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px;
  list-style: none;
  cursor: pointer;
  font-size: 14px;
  line-height: 1.6;
  padding-block: 22px;
  font-weight: 550;}
.ds-faq-list summary::-webkit-details-marker{display: none;}
.ds-faq-list summary:hover{color: var(--brand-deep,#087f70);}
.ds-faq-list summary svg{transition: transform 0.2s;}
.ds-faq-list details[open] summary svg{transform: rotate(180deg);}
.ds-faq-answer{padding-bottom: 23px;}
.ds-faq-answer p{color: var(--muted,#536b66);
  font-size: 13px;
  line-height: 1.85;}
.ds-faq-answer .ds-text-link{font-size: 12px;
  color: var(--brand-deep,#087f70);
  margin-top: 8px;}.ds-faq-list{font-family:"Inter",ui-sans-serif,system-ui,sans-serif;color:var(--ink,#16332f);}.ds-faq-answer p{margin:0}.ds-faq-list summary:focus-visible{outline:3px solid var(--brand-deep,#087f70);outline-offset:5px;border-radius:3px}
@media(prefers-reduced-motion:reduce){.ds-button,.ds-text-link svg,.ds-contact-form-wrap input,.ds-desktop-nav a,.ds-scenario-tabs button,.ds-faq-list summary svg{transition-duration:.01ms!important;animation-duration:.01ms!important;animation-iteration-count:1!important}}
